function searchMatrix(matrix: number[][], target: number): boolean {
  const m = matrix.length;
  const n = matrix[0].length;

  // Считаем матрицу одним отсортированным массивом длины m * n:
  // индекс k соответствует клетке (k / n, k % n)
  let lo = 0;
  let hi = m * n - 1;

  while (lo <= hi) {
    const mid = lo + ((hi - lo) >> 1);
    const value = matrix[Math.floor(mid / n)][mid % n];

    if (value === target) return true;
    if (value < target) {
      // Искомое правее
      lo = mid + 1;
    } else {
      // Искомое левее
      hi = mid - 1;
    }
  }

  return false;
}

// Время: O(log(m * n))
// Память: O(1)
